 string folder;int errors;readonly StringBuilder report=new StringBuilder();BowlingMatch m;void Check(bool yes,string label){report.AppendLine((yes?"PASS ":"FAIL ")+label);if(!yes)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+message+"\n"+stack);Write();}}IEnumerator Until(Func<bool> condition,float seconds){float end=Time.realtimeSinceStartup+seconds;while(!condition()&&Time.realtimeSinceStartup<end)yield return null;}
