eturns+" errors="+errors);next=Time.realtimeSinceStartup+3;}yield return null;}Check(m.Finished,"complete normal physical four-lane game seed="+(900+game));Check(cap,"all observed wall responses respect outgoing speed/energy caps");Check(provenance&&!early,"positive pinfall has real contact and machinery stays overhead during live play");allStrikes+=strikes;allSpares+=spares;for(int i=0;i<4;i++){if(m.setup.players[i].score.FrameRolls(9).Count==3)bonuses++;report.AppendLine("AI_GAME seed="+(900+game)+" difficulty="+m.setup.players[i].difficulty+" lane="+i+" total="+m.setup.players[i].score.ResolvedTotal+" deliveries="+m.setup.players[i].score.Deliveries+" tenth="+m.setup.players[i].score.Symbols(9));}report.AppendLine("AGGREGATE strikes="+strikes+" spares="+spares+" gutters="+gutters+" actualReturns="+actualReturns);Write();if(errors>0)break;}
 Check(allStrikes>0&&allSpares>0,"ordinary physical games include strikes and spares");Check(bonuses>0,"actual tenth-frame bonus deliveries complete with rack resets");m.ChangeSetup();m.PresetAI(2,BowlingMode.HotSeat);foreach(var lane in m.lanes)lane.ai.enabled=true;Check(m.StartMatch(),"two-AI sequential hot-seat rematch starts");Time.timeScale=Application.isEditor?8:4;yield return Until(()=>m.Finished,300);Check(m.Finished&&m.setup.players[0].score.Finished&&m.setup.players[1].score.Finished,"autonomous hot-seat full game progresses across frames and participants");report.AppendLine("HOTSEAT totals="+m.setup.players[0].score.ResolvedTotal+","+m.setup.players[1].score.ResolvedTotal+" deliveries="+m.setup.players[0].score.Deliveries+","+m.setup.players[1].score.Deliveries);Write();
 // Explicit initialized contact/state fixtures below, separate from AI games.
 OneLane();Time.timeScale=3;yield return new WaitForSeconds(.2f);var l=m.lanes[0];foreach(var pin in l.pins)pin.Freeze();var b=l.truck.body;var wall0=l.rebound;int count=wall0.Returns;var watch=l.truck.gameObject.AddComponent<BowlingWallContactWatch>();watch.wall=wall0.GetComponent<Collider>();var position=new Vector3(l.center,.06f,l.pinLine+5.5f);b.position=position;b.rotation=Quaternion.identity;l.truck.transform.SetPositionAndRotation(position,Quaternion.identity);b.linearVelocity=Vector3.forward*8;b.angularVelocity=Vector3.zero;l.truck.Control(Vector2.zero);Physics.SyncTransforms();yield return Until(()=>watch.Contacts>0,4);Check(watch.Contacts>0&&wall0.Returns==count,"real truck/wall impact gets ordinary PhysX contact and no enhanced pin impulse");Destroy(watch);m.ChangeSetup();
 OneLane();Time.timeScale=3;yield return new WaitForSeconds(.2f);l=m.lanes[0];l.truck.Clear();foreach(var pin in l.pins)pin.Freeze();var p=l.pins[0];p.Release();position=new Vector3(l.center,.08f,l.rebound.transform.position.z-1.4f);p.body.position=position;p.body.rotation=Quaternion.Euler(0,0,88);p.transform.SetPositionAndRotation(position,p.body.rotation);p.body.linearVelocity=new Vector3(1.2f,0,8);p.body.angularVelocity=new Vector3(0,1,0);Physics.SyncTransforms();count=l.rebound.Returns;yield return Until(()=>l.rebound.Returns>count,3);Check(l.rebound.Returns==count+1&&l.rebound.LastNormalSpeed>.8f,"actual qualifying pin/front-wall contact returns once");yield return new WaitForSeconds(.2f);Check(l.rebound.Returns==count+1,"sustained/repeated early contact cannot stack boosts");Check(l.rebound.LastOutgoing.z< -3&&Mathf.Abs(l.rebound.LastOutgoing.y)<=2.51f,"strong reverse component remains around pin height");yield return Capture("spring-return");m.Pause();var pinPos=p.body.position;var velocity=p.body.linearVelocity;yield return new WaitForSecondsRealtime(.12f);Check(p.body.position==pinPos&&p.body.linearVelocity==velocity,"pause preserves live return motion");m.Resume();Time.timeScale=3;yield return new WaitForSeconds(.2f);m.ChangeSetup();
 OneLane();Time.timeScale=3;yield return new WaitForSeconds(.2f);l=m.lanes[0];l.truck.Clear();foreach(var pin in l.pins)pin.Freeze();p=l.pins[0];p.Release();p.body.position=new Vector3(l.center,.08f,l.pinLine);p.body.rotation=Quaternion.Euler(0,0,85);p.transform.SetPositionAndRotation(p.body.position,p.body.rotation);Physics.SyncTransforms();yield return new WaitForSeconds(.5f);Check(p.RegisteredDown,"real toppled pin registers after stable down interval");p.Freeze();p.body.position=l.rack[0];p.body.rotation=Quaternion.identity;p.transform.SetPositionAndRotation(l.rack[0],Quaternion.identity);Physics.SyncTransforms();Check(!p.Down&&p.RegisteredDown,"registered down remains latched when fixture reseats it upright");int previous=l.ScoreLocks;l.EndDelivery("Registered-down state fixture");yield return Until(()=>l.ScoreLocks>previous,4);Check(l.LastPins==1&&l.Owner.score.RemainingPins==9,"latched actual down state counts once without automatic strike");m.ChangeSetup();Check(m.StartMatch(),"rematch resets wall, pin latch and legal rack");Check(!m.lanes[0].pins[0].RegisteredDown&&m.lanes[0].Owner.score.RemainingPins==10,"clean rack and score on restart");m.ChangeSetup();SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1,"clean menu return after repeated full matches");report.AppendLine("ERRORS="+errors+". Full ordinary AI games plus explicitly initialized physical/state fixtures; no human/hardware or GPU benchmark claim.");File.WriteAllText(folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;Time.timeScale=1;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
